"""Editor script: create the particle / shadow materials in /Game/Particles (no game data; regenerated by this script)."""
# 0x1F08D0
import unreal

PATH = "/Game/Particles"
assets = unreal.EditorAssetLibrary
mel = unreal.MaterialEditingLibrary
tools = unreal.AssetToolsHelpers.get_asset_tools()

# The GsSprite node: (Cs / 255, As / 128) from the linear texture sample and the vertex colour bytes (SSXGs::SpriteHlsl).
GS_SPRITE = """float3 ct = floor(Tex.rgb * 255.0 + 0.001);
float at = min(floor((floor(Tex.a * 255.0 + 0.001) + 1.0) * 0.5), 128.0);
float3 cv = floor(VC.rgb * 255.0 + 0.5);
float av = floor(VC.a * 255.0 + 0.5);
float3 cs = min(floor(ct * cv / 128.0), 255.0);
float sa = min(floor(at * av / 128.0), 255.0);
return float4(cs / 255.0, sa / 128.0);
"""

ADD = "return S.rgb * S.a;"
DARKEN = "return max(1.0 - S.a, 0.0).xxx;"
BRIGHTEN = "return (1.0 + S.a).xxx;"
SHADOW_UV = """
float3 P = CamC + Rel * (SD / max(PD, 0.001));
float rider = (CD.r <= SD * 1.0005 + 0.5) ? 1.0 : 0.0;
float a = P.x * Ax.x + P.y * Ax.y;
float r = P.y * Ax.x - P.x * Ax.y;
float inside = (abs(r) < HX && abs(a) < HY && P.z > ZMin && P.z < ZMax && rider < 0.5) ? 1.0 : 0.0;
return float3(0.5 + r / (2.0 * HX), 0.5 - a / (2.0 * HY), inside);
"""
SHADOW_SHADE = """
float m = saturate(1.0 - RT.a) * UVI.z;
// GS ALPHA mode 7 = Cd - Cs As >> 7, clamped. The silhouette texel reads back as Cs = 32 with
// As = 0x80 (GS dump): subtract Sub = 32 / 255 at full cover, the bilinear coverage m at the edges.
// The scene colour is the PS2 value itself (PS2 colour space), so the subtraction is done on it directly.
float s = saturate(m * Sub);
float3 e = max(Scene.rgb / View.PreExposure, 0.0);
if (Mode < 0.5)
{
    return max(e - s, 0.0) / max(e, 1e-5);
}
return (1.0 - s).xxx;
"""

F1, F3, F4 = (unreal.CustomMaterialOutputType.CMOT_FLOAT1, unreal.CustomMaterialOutputType.CMOT_FLOAT3,
              unreal.CustomMaterialOutputType.CMOT_FLOAT4)


def connect(src, out, dst, inp):
    if not mel.connect_material_expressions(src, out, dst, inp):
        raise RuntimeError(f"cannot connect {src.get_name()}.{out} -> {dst.get_name()}.{inp}")


def connect_prop(src, out, prop):
    if not mel.connect_material_property(src, out, prop):
        raise RuntimeError(f"cannot connect {src.get_name()}.{out} -> {prop}")


def expr(mat, cls, x, y, **props):
    e = mel.create_material_expression(mat, cls, x, y)
    for k, v in props.items():
        e.set_editor_property(k, v)
    return e


def custom(mat, x, y, code, out_type, inputs, desc):
    e = expr(mat, unreal.MaterialExpressionCustom, x, y)
    e.set_editor_property("code", code)
    e.set_editor_property("output_type", out_type)
    e.set_editor_property("description", desc)
    ins = []
    for n, _ in inputs:
        ci = unreal.CustomInput()
        ci.set_editor_property("input_name", n)
        ins.append(ci)
    e.set_editor_property("inputs", ins)
    for n, (src, out) in inputs:
        connect(src, out, e, n)
    return e


def new_material(name, blend):
    full = f"{PATH}/{name}"
    if assets.does_asset_exist(full):
        m = assets.load_asset(full)
        for _ in range(16):
            if mel.get_num_material_expressions(m) == 0:
                break
            mel.delete_all_material_expressions(m)
    else:
        m = tools.create_asset(name, PATH, unreal.Material, unreal.MaterialFactoryNew())
    m.set_editor_property("shading_model", unreal.MaterialShadingModel.MSM_UNLIT)
    m.set_editor_property("blend_mode", blend)
    m.set_editor_property("two_sided", True)
    return m


def finish(m):
    mel.recompile_material(m)
    assets.save_asset(m.get_path_name().split(".")[0], only_if_is_dirty=False)
    unreal.log(f"[ssx] created {m.get_path_name()}")


def tex_param(m, name, x, y, linear=False):
    e = expr(m, unreal.MaterialExpressionTextureSampleParameter2D, x, y, parameter_name=name)
    e.set_editor_property("texture", unreal.load_asset("/Game/World/T_SSXLightmapNeutral" if linear
                                                       else "/Engine/EngineResources/WhiteSquareTexture"))
    e.set_editor_property("sampler_type", unreal.MaterialSamplerType.SAMPLERTYPE_LINEAR_COLOR if linear
                          else unreal.MaterialSamplerType.SAMPLERTYPE_COLOR)
    return e


def sprite_inputs(m):
    tex = tex_param(m, "Tex", -900, -100, linear=True)   # PARTICLE.SSH textures load linear (stored bytes)
    vc = expr(m, unreal.MaterialExpressionVertexColor, -1100, 150)
    vc4 = expr(m, unreal.MaterialExpressionAppendVector, -900, 150)
    connect(vc, "", vc4, "A")
    connect(vc, "A", vc4, "B")
    return tex, vc4


def tex4(m, tex, x, y):
    """RGBA of the sample as one float4."""
    app = expr(m, unreal.MaterialExpressionAppendVector, x, y)
    connect(tex, "RGB", app, "A")
    connect(tex, "A", app, "B")
    return app


def gs_sprite(m):
    """The GsSprite node of a sprite material: float4 (Cs / 255, As / 128)."""
    tex, vc = sprite_inputs(m)
    return custom(m, -600, 0, GS_SPRITE, F4, [("Tex", (tex4(m, tex, -750, -100), "")), ("VC", (vc, ""))], "GsSprite")


SOFT_DEPTH_SPRITE = "return float4(S.rgb, (PD <= CD.r * 1.0005 + 0.5) ? S.a : 0.0);"


def gs_sprite_depth(m):
    """gs_sprite with the soft-prop depth test (SOFT_DEPTH_SPRITE)."""
    node = gs_sprite(m)
    pd = expr(m, unreal.MaterialExpressionPixelDepth, -800, 350)
    cd = expr(m, unreal.MaterialExpressionSceneTexture, -800, 450, scene_texture_id=unreal.SceneTextureId.PPI_CUSTOM_DEPTH)
    return custom(m, -450, 250, SOFT_DEPTH_SPRITE, F4, [("S", (node, "")), ("PD", (pd, "")), ("CD", (cd, "Color"))], "SoftDepth")


def sprite_material(name, blend, code, opacity=False):
    m = new_material(name, blend)
    node = gs_sprite_depth(m)
    c = custom(m, -300, 0, code, F3, [("S", (node, ""))], name[5:])
    connect_prop(c, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    if opacity:
        a = expr(m, unreal.MaterialExpressionComponentMask, -300, 200, r=False, g=False, b=False, a=True)
        connect(node, "", a, "")
        sat = expr(m, unreal.MaterialExpressionSaturate, -150, 200)
        connect(a, "", sat, "")
        connect_prop(sat, "", unreal.MaterialProperty.MP_OPACITY)
    finish(m)


sprite_material("M_SSXParticleAdd", unreal.BlendMode.BLEND_ADDITIVE, ADD)
sprite_material("M_SSXParticleAlpha", unreal.BlendMode.BLEND_TRANSLUCENT, "return S.rgb;", True)
sprite_material("M_SSXParticleDarken", unreal.BlendMode.BLEND_MODULATE, DARKEN)
sprite_material("M_SSXParticleBrighten", unreal.BlendMode.BLEND_MODULATE, BRIGHTEN)

# TODO: layer-3 props cover the trail too (not excluded here).
TRAIL_UNDER_RIDER = """
float rider = (CD.r <= SD * 1.0005 + 0.5) ? 1.0 : 0.0;
return rider > 0.5 ? float3(1.0, 1.0, 1.0) : C;
"""


def trail_material(name, code):
    m = new_material(name, unreal.BlendMode.BLEND_MODULATE)
    node = gs_sprite_depth(m)
    c = custom(m, -300, 0, code, F3, [("S", (node, ""))], name[5:])
    sd = expr(m, unreal.MaterialExpressionSceneDepth, -500, 250)
    cd = expr(m, unreal.MaterialExpressionSceneTexture, -500, 350, scene_texture_id=unreal.SceneTextureId.PPI_CUSTOM_DEPTH)
    out = custom(m, -100, 100, TRAIL_UNDER_RIDER, F3, [("C", (c, "")), ("SD", (sd, "")), ("CD", (cd, "Color"))],
                 "UnderRider")
    connect_prop(out, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    finish(m)


trail_material("M_SSXTrailDarken", DARKEN)
trail_material("M_SSXTrailBrighten", BRIGHTEN)

m = new_material("M_SSXShadowProject", unreal.BlendMode.BLEND_MODULATE)
m.set_editor_property("two_sided", False)
m.set_editor_property("disable_depth_test", True)
rel = expr(m, unreal.MaterialExpressionWorldPosition, -1500, -300,
           world_position_shader_offset=unreal.WorldPositionIncludedOffsets.WPT_CAMERA_RELATIVE)
sd = expr(m, unreal.MaterialExpressionSceneDepth, -1500, -200)
pd = expr(m, unreal.MaterialExpressionPixelDepth, -1500, -100)
cam = expr(m, unreal.MaterialExpressionCameraPositionWS, -1700, 0)
centre = expr(m, unreal.MaterialExpressionVectorParameter, -1700, 100, parameter_name="ShadowCentre",
              default_value=unreal.LinearColor(0, 0, 0, 0))
cd = expr(m, unreal.MaterialExpressionSceneTexture, -1700, -400, scene_texture_id=unreal.SceneTextureId.PPI_CUSTOM_DEPTH)
camc = expr(m, unreal.MaterialExpressionSubtract, -1500, 50)
connect(cam, "", camc, "A")
connect(centre, "RGB", camc, "B")
scal = {}
axis = expr(m, unreal.MaterialExpressionVectorParameter, -1700, 200, parameter_name="ShadowAxis",
            default_value=unreal.LinearColor(1, 0, 0, 0))
for i, (n, dv) in enumerate((("ShadowHalfX", 100.0), ("ShadowHalfY", 100.0), ("ShadowZMin", -3000.0),
                             ("ShadowZMax", 100.0), ("ShadowSub", 32.0 / 255.0), ("ShadowMode", 0.0))):
    scal[n] = expr(m, unreal.MaterialExpressionScalarParameter, -1500, 200 + 90 * i, parameter_name=n,
                   default_value=dv)
uvi = custom(m, -1150, -100, SHADOW_UV, F3,
             [("Rel", (rel, "")), ("SD", (sd, "")), ("PD", (pd, "")), ("CD", (cd, "Color")), ("CamC", (camc, "")),
              ("HX", (scal["ShadowHalfX"], "")), ("HY", (scal["ShadowHalfY"], "")), ("Ax", (axis, "RGB")),
              ("ZMin", (scal["ShadowZMin"], "")),
              ("ZMax", (scal["ShadowZMax"], ""))], "ShadowUV")
uv = expr(m, unreal.MaterialExpressionComponentMask, -900, -100, r=True, g=True, b=False, a=False)
connect(uvi, "", uv, "")
rt = tex_param(m, "ShadowTex", -700, -150, linear=True)
connect(uv, "", rt, "UVs")
scene = expr(m, unreal.MaterialExpressionSceneColor, -700, 100)
shade = custom(m, -350, 0, SHADOW_SHADE, F3,
               [("RT", (tex4(m, rt, -500, -150), "")), ("UVI", (uvi, "")), ("Scene", (scene, "")),
                ("Sub", (scal["ShadowSub"], "")), ("Mode", (scal["ShadowMode"], ""))], "ShadowShade")
connect_prop(shade, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
finish(m)

GHOST = """
float3 c = min(floor(Tex.rgb * 255.0 + 0.001) * Tint.rgb * min(floor((floor(Tex.a * 255.0 + 0.001) + 1.0) * 0.5), 128.0) / 128.0, 255.0);
return c / 255.0;
"""
m = new_material("M_SSXGhost", unreal.BlendMode.BLEND_ADDITIVE)
m.set_editor_property("used_with_skeletal_mesh", True)
m.set_editor_property("used_with_morph_targets", True)
tex = tex_param(m, "Tex", -900, -100, linear=True)
tint = expr(m, unreal.MaterialExpressionVectorParameter, -900, 150, parameter_name="Tint",
            default_value=unreal.LinearColor(1, 1, 1, 1))
c = custom(m, -400, 0, GHOST, F3, [("Tex", (tex4(m, tex, -650, -100), "")), ("Tint", (tint, "RGB"))], "Ghost")
connect_prop(c, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
finish(m)

LENS_OCCLUSION = """
float4 clip = mul(float4(VP, 1.0), View.ViewToClip);
if (clip.w <= 0.0) return 0.0;
float2 ndc = clip.xy / clip.w;
float2 px = float2((ndc.x + 1.0) * 256.0, (1.0 - ndc.y) * 224.0);
float bw = Blk.x;
float bh = Blk.y;
float2 o = float2(clamp(trunc(px.x - bw * 0.5), 0.0, 512.0 - bw), clamp(trunc(px.y - bh * 0.5), 0.0, 448.0 - bh));
float zp = VP.z - Pull;
float counted = 0.0;
float inside = 0.0;
[loop] for (int j = 0; j < (int)bh; ++j)
{
    [loop] for (int i = 0; i < (int)bw; ++i)
    {
        float2 uv = (o + float2(i, j) + 0.5) / float2(512.0, 448.0);
        if (uv.x >= 0.0 && uv.x < 1.0 && uv.y >= 0.0 && uv.y < 1.0)
        {
            inside += 1.0;
            if (CalcSceneDepth(ViewportUVToBufferUV(uv)) >= zp) counted += 1.0;
        }
    }
}
float total = max(bw * bh, 1.0);
float v = (inside == total) ? counted / total : max((counted - floor(total * 0.5)) / floor(total * 0.5), 0.0);
return v + SD * 0.0;
"""
LENS_SPRITE = "return S.rgb * S.a * V;"
LENS_FAN = """
float3 cv = floor(VC.rgb * 255.0 + 0.5);
float av = floor(VC.a * 255.0 + 0.5);
return cv / 255.0 * (av / 128.0) * V;
"""


def lens_occlusion(m):
    """The visibility V of the vertex's occlusion point (float)."""
    t1 = expr(m, unreal.MaterialExpressionTextureCoordinate, -1500, 400, coordinate_index=1)
    t2 = expr(m, unreal.MaterialExpressionTextureCoordinate, -1500, 500, coordinate_index=2)
    t3 = expr(m, unreal.MaterialExpressionTextureCoordinate, -1500, 600, coordinate_index=3)
    z = expr(m, unreal.MaterialExpressionComponentMask, -1300, 500, r=True, g=False, b=False, a=False)
    connect(t2, "", z, "")
    pull = expr(m, unreal.MaterialExpressionComponentMask, -1300, 560, r=False, g=True, b=False, a=False)
    connect(t2, "", pull, "")
    wp = expr(m, unreal.MaterialExpressionAppendVector, -1150, 450)
    connect(t1, "", wp, "A")
    connect(z, "", wp, "B")
    vp = expr(m, unreal.MaterialExpressionTransformPosition, -1000, 450,
              transform_source_type=unreal.MaterialPositionTransformSource.TRANSFORMPOSSOURCE_WORLD,
              transform_type=unreal.MaterialPositionTransformSource.TRANSFORMPOSSOURCE_VIEW)
    connect(wp, "", vp, "")
    sd = expr(m, unreal.MaterialExpressionSceneDepth, -1000, 650)
    return custom(m, -750, 450, LENS_OCCLUSION, F1,
                  [("VP", (vp, "")), ("Pull", (pull, "")), ("Blk", (t3, "")), ("SD", (sd, ""))], "LensOcclusion")


def lens_material(name):
    m = new_material(name, unreal.BlendMode.BLEND_ADDITIVE)
    m.set_editor_property("disable_depth_test", True)
    return m


m = lens_material("M_SSXLensSprite")
v = lens_occlusion(m)
node = gs_sprite(m)
c = custom(m, -300, 0, LENS_SPRITE, F3, [("S", (node, "")), ("V", (v, ""))], "LensSprite")
connect_prop(c, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
finish(m)

m = lens_material("M_SSXLensFan")
v = lens_occlusion(m)
vc = expr(m, unreal.MaterialExpressionVertexColor, -1100, 150)
vc4 = expr(m, unreal.MaterialExpressionAppendVector, -900, 150)
connect(vc, "", vc4, "A")
connect(vc, "A", vc4, "B")
c = custom(m, -300, 0, LENS_FAN, F3, [("VC", (vc4, "")), ("V", (v, ""))], "LensFan")
connect_prop(c, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
finish(m)
